import io, os, sys, urllib.request, zipfile
CACHE = os.environ.get("REPRO_DATA_CACHE", ".")
print(CACHE, os.path.isdir(CACHE))
try:
    print(os.listdir(CACHE))
except Exception as e:
    print("err", e)

cands = {
 "kidney": ["https://archive.ics.uci.edu/static/public/336/chronic+kidney+disease.zip"],
 "mammo": ["https://archive.ics.uci.edu/static/public/161/mammographic+mass.zip"],
 "cancer": ["https://archive.ics.uci.edu/static/public/15/breast+cancer+wisconsin+original.zip",
            "https://archive.ics.uci.edu/static/public/15/breast+cancer+wisconsin+(original).zip"],
 "mushroom": ["https://archive.ics.uci.edu/static/public/73/mushroom.zip"],
}
for k, urls in cands.items():
    for u in urls:
        try:
            with urllib.request.urlopen(u, timeout=30) as r:
                b = r.read()
            zf = zipfile.ZipFile(io.BytesIO(b))
            print(k, "OK", u, len(b), zf.namelist())
            break
        except Exception as e:
            print(k, "FAIL", u, repr(e)[:120])

